import nbformat as nbf
RAW = "https://raw.githubusercontent.com/sweeden-ttu/profile/stable/notebooks/usd-llm/usdlab.py"
def badge(name): return f'<a href="https://colab.research.google.com/github/sweeden-ttu/profile/blob/stable/notebooks/usd-llm/{name}" target="_parent"><img src="https://colab.research.google.com/assets/colab-badge.svg" alt="Open In Colab"/></a>'
def nb(name, cells):
    n = nbf.v4.new_notebook(); n.metadata = {"colab": {"provenance": []}, "kernelspec": {"name": "python3", "display_name": "Python 3"}, "language_info": {"name": "python"}}
    n.cells = [nbf.v4.new_markdown_cell(badge(name))] + [nbf.v4.new_markdown_cell(c[1]) if c[0] == "md" else nbf.v4.new_code_cell(c[1]) for c in cells]
    nbf.write(n, name); print("wrote", name)

nb("01_usd_corpus_and_usdfid.ipynb", [
 ("md", "# 01 · USD corpus, corruption families and the `usdfid` metric\n\nCPU only. This notebook builds the **repair-task** data (task O1 in the plan) and the layered fidelity score the challenge would use. Everything here runs on a free Colab CPU runtime in a few minutes.\n\nPlan and context: <https://scottweeden.online/projects/usd-scene-llm/>"),
 ("code", f"!pip -q install usd-core numpy tokenizers matplotlib\n!wget -q -O usdlab.py {RAW}\nimport usdlab as U, json, numpy as np\nfrom pxr import Usd\nprint('USD', Usd.GetVersion())"),
 ("md", "## 1. A licence-clean reference stage\n`build_toy_knee()` writes a procedural stand-in for the Archetypal Knee (bones, cartilage, menisci) in millimetres, Z-up, with `knee:*` attributes on every mesh. Swap in the real archetype (section 5) once the pipeline works."),
 ("code", "stage = U.build_toy_knee()          # keep a reference to the stage (its layer dies with it)\nref = stage.GetRootLayer().ExportToString()\nprint(len(ref), 'characters'); print(ref[:800])"),
 ("md", "## 2. Corruption families\nHold out whole *families* between train and test so the task rewards generalisation, not memorised templates."),
 ("code", "for fam in U.CORRUPTIONS:\n    bad, note = U.corrupt(ref, fam, seed=1)\n    print(f'{fam:20s} {note}')"),
 ("md", "## 3. `usdfid`: a layered score\nL0 parse/compose gate → L1 validation (UsdValidation) → L2 structure (prim-path Jaccard, types, stage metadata) → L3 attributes (world transforms, `knee:*` values) → L4 geometry (Chamfer and F-score at τ = 1% of the bounding-box diagonal)."),
 ("code", "print(U.usdfid(ref, ref))\nfor fam in U.CORRUPTIONS:\n    bad, _ = U.corrupt(ref, fam, seed=3)\n    r = U.usdfid(ref, bad)\n    print(f\"{fam:20s} score={r['score']:.3f}  L2_meta={r['L2_metadata']:.2f}  L3={r['L3_attributes']:.3f}  F={r['L4_fscore']:.3f}\")\nprint('unparseable ->', U.usdfid(ref, '#usda 1.0\\n( not valid')['score'])"),
 ("md", "## 4. Tokenizer audit\nCount tokens before choosing a base model. Per-digit tokenizers (Gemma, Qwen3, Mistral) pay heavily for inline float arrays; a payload reference keeps geometry out of the model's output."),
 ("code", "from tokenizers import Tokenizer\nforms = {'full float': U.serialize(stage), '3 dp': U.serialize(stage, 3), 'integer mm': U.serialize(stage, 0), 'payload': U.serialize(stage, payload=True)}\nfor name, repo in {'Llama-3.x': 'unsloth/Llama-3.2-1B-Instruct', 'Gemma 4': 'unsloth/gemma-4-E4B-it', 'Qwen3': 'Qwen/Qwen3-8B'}.items():\n    tok = Tokenizer.from_pretrained(repo)\n    print(f'{name:10s}', {k: len(tok.encode(v).ids) for k, v in forms.items()})"),
 ("md", "## 5. SFT pairs\n`{\"input\", \"output\"}` rows are the format Megatron-Bridge's `GPTSFTDatasetConfig` and most HF SFT trainers read. Families `jitter_points` are left out of the text task because payload form hides point arrays."),
 ("code", "rows = U.make_sft_pairs(700, seed=0)\ntest_fams = {'units', 'swap_label'}            # held-out corruption families\ntrain = [r for r in rows if r['family'] not in test_fams]; test = [r for r in rows if r['family'] in test_fams]\nfor name, part in [('training.jsonl', train), ('validation.jsonl', test)]:\n    with open(name, 'w') as f:\n        for r in part: f.write(json.dumps({'input': r['input'], 'output': r['output']}) + '\\n')\nprint(len(train), 'train /', len(test), 'held-out family rows')"),
 ("md", "### Optional: the real Archetypal Knee (CC BY-NC 4.0)\nRequires Kaggle credentials in Colab Secrets (`KAGGLE_USERNAME`, `KAGGLE_KEY`)."),
 ("code", "# import kagglehub, os\n# from google.colab import userdata\n# os.environ['KAGGLE_USERNAME'] = userdata.get('KAGGLE_USERNAME'); os.environ['KAGGLE_KEY'] = userdata.get('KAGGLE_KEY')\n# path = kagglehub.dataset_download('scottweeden/the-archetypal-knee')\n# real = Usd.Stage.Open(f'{path}/archetype/usd/knee_archetype.usda')\n# print(sum(1 for p in real.Traverse()), 'prims')"),
])

nb("02_usd_qlora_unsloth_colab.ipynb", [
 ("md", "# 02 · QLoRA prototype on Colab (Unsloth)\n\nGPU runtime (L4 or A100). Phase 1 of the plan: a fast, cheap check that a small model can learn the repair task **before** spending cluster time on Megatron-Bridge.\n\n**Status: scaffold, not yet run end-to-end.** Model ids, the Unsloth API and memory figures follow Unsloth's Gemma 4 guide as of October 2026; pin versions when you run it. Exit criterion: valid-parse rate and mean `usdfid` on the held-out families beat the zero-shot base model."),
 ("code", f"!pip -q install unsloth usd-core tokenizers\n!wget -q -O usdlab.py {RAW}\nimport usdlab as U, json, torch\nprint(torch.cuda.get_device_name(0))"),
 ("code", "# Recreate the data from notebook 01 (or upload training.jsonl / validation.jsonl)\nrows = U.make_sft_pairs(700, seed=0)\ntest_fams = {'units', 'swap_label'}\ntrain = [r for r in rows if r['family'] not in test_fams]; test = [r for r in rows if r['family'] in test_fams][:60]"),
 ("code", "from unsloth import FastLanguageModel\nMODEL = 'unsloth/gemma-4-E4B-it'   # E4B LoRA fits an L4; use a 26B/31B QLoRA only on A100 80GB\nmodel, tokenizer = FastLanguageModel.from_pretrained(MODEL, max_seq_length=8192, load_in_4bit=True)\nmodel = FastLanguageModel.get_peft_model(model, r=16, lora_alpha=16, lora_dropout=0.0,\n    target_modules=['q_proj','k_proj','v_proj','o_proj','gate_proj','up_proj','down_proj'])"),
 ("code", "from datasets import Dataset\ndef fmt(r):\n    msgs = [{'role': 'user', 'content': r['input']}, {'role': 'assistant', 'content': r['output']}]\n    return {'text': tokenizer.apply_chat_template(msgs, tokenize=False)}\nds = Dataset.from_list(train).map(fmt)"),
 ("code", "from trl import SFTTrainer, SFTConfig\ntrainer = SFTTrainer(model=model, tokenizer=tokenizer, train_dataset=ds,\n    args=SFTConfig(dataset_text_field='text', per_device_train_batch_size=1, gradient_accumulation_steps=8,\n                   num_train_epochs=1, learning_rate=2e-4, logging_steps=10, output_dir='usd_lora',\n                   bf16=torch.cuda.is_bf16_supported()))\n# Train on completions only (the .usda answer), not on the prompt:\n# from unsloth.chat_templates import train_on_responses_only  -> see Unsloth docs for the Gemma 4 markers\ntrainer.train()"),
 ("code", "FastLanguageModel.for_inference(model)\nimport numpy as np\nref = test[0]['output']; scores, parsed = [], 0\nfor r in test:\n    msgs = [{'role': 'user', 'content': r['input']}]\n    ids = tokenizer.apply_chat_template(msgs, add_generation_prompt=True, return_tensors='pt').to('cuda')\n    out = tokenizer.decode(model.generate(ids, max_new_tokens=3000, do_sample=False)[0][ids.shape[1]:], skip_special_tokens=True)\n    res = U.usdfid(ref, out); parsed += res['L0_parse']; scores.append(res['score'])\nprint(f'valid parse {parsed}/{len(test)}  mean usdfid {np.mean(scores):.3f}')"),
 ("code", "model.save_pretrained('usd_lora'); tokenizer.save_pretrained('usd_lora')   # adapter for the vLLM + ADK arena"),
])

nb("03_megatron_bridge_sft.ipynb", [
 ("md", "# 03 · Scaling up with Megatron-Bridge (cluster)\n\nThis notebook is a **runbook**: it prepares the data on Colab and prints the commands to run on an 8×A100/H100 node. Megatron-LM's own docs now point HF↔Megatron conversion to **Megatron-Bridge**, which pins Megatron-Core as a submodule (`3rdparty/Megatron-LM`). Use the upstream pin unless you carry core patches in the `sweeden-ttu/Megatron-LM` fork.\n\nVerified against Megatron-Bridge docs/PyPI (0.5.x–0.6.x) in October 2026; re-check names against the version you pin."),
 ("code", f"!wget -q -O usdlab.py {RAW}\n!pip -q install usd-core\nimport usdlab as U, json\nrows = U.make_sft_pairs(5000, seed=0)\ntest_fams = {{'units', 'swap_label'}}\nwith open('training.jsonl','w') as f:\n    [f.write(json.dumps({{'input': r['input'], 'output': r['output']}})+'\\n') for r in rows if r['family'] not in test_fams]\nwith open('validation.jsonl','w') as f:\n    [f.write(json.dumps({{'input': r['input'], 'output': r['output']}})+'\\n') for r in rows if r['family'] in test_fams]\n!wc -l training.jsonl validation.jsonl"),
 ("md", "## On the cluster\n```bash\n# container: nvcr.io/nvidia/nemo:<tag>   or   pip install megatron-bridge   (Python 3.12)\ngit clone https://github.com/NVIDIA-NeMo/Megatron-Bridge && cd Megatron-Bridge\n\n# 1. HF -> Megatron checkpoint (CPU is fine)\n./scripts/conversion/convert.sh import --executor local --device cpu \\\n    --hf-model Qwen/Qwen3-8B --megatron-path ./ckpt/qwen3_8b\n```"),
 ("code", "RECIPE = '''\nfrom megatron.bridge.recipes.qwen.qwen3 import qwen3_8b_peft_config   # LoRA, TP=1/PP=1, one 8-GPU node\ncfg = qwen3_8b_peft_config(peft_scheme=\"lora\")\ncfg.checkpoint.pretrained_checkpoint = \"./ckpt/qwen3_8b\"\n# cfg.dataset -> GPTSFTDatasetConfig(dataset_root=\"usd_sft/\", seq_length=8192, ...)   # training.jsonl / validation.jsonl\n# offline packing: enable_offline_packing=True, PackedSequenceSpecs(packed_sequence_size=8192)\n'''\nopen('finetune_usd.py','w').write(RECIPE)\nprint('uv run python -m torch.distributed.run --nproc-per-node=8 finetune_usd.py')"),
 ("md", "## Export the adapter and evaluate\n```bash\nuv run python examples/conversion/adapter/export_adapter.py --hf-model-id Qwen/Qwen3-8B \\\n    --megatron-peft-checkpoint <ckpt> --output-hf-path ./usd_lora\nuv run python examples/conversion/adapter/verify_adapter.py --hf-model-id Qwen/Qwen3-8B --hf-adapter-path ./usd_lora\n```\nThen serve `./usd_lora` with vLLM and score it with `usdlab.usdfid` exactly as in notebook 02.\n\n| Recipe | TP / PP | Nodes |\n|---|---|---|\n| `qwen3_8b_peft_config` | 1 / 1 | 1 |\n| `qwen3_32b_peft_config` | 1 / 1 + recompute | 1 |\n| `qwen3_8b_sft_config` | 4 / 1 | 1 |\n| `qwen3_32b_sft_config` | 8 / 2 | 2 |"),
])
